        let qr = QueryRunner{
            pq:        query_parser.ParsedQuery{
                table_name:    "",
                where_col_idx: -1,
                where_op:      0,
                where_val_int: 0,
                order_col_idx: -1,
                order_desc:    false,
                limit_count:   -1,
                has_error:     false,
                error_code:    0,
            },
            exec_plan: planner.ExecPlan{
                plan_type:  0,
                index_col:  -1,
                est_rows:   0,
                cost:       0,
                error_code: 0,
            },
            phys_plan: physical_plan.physical_plan_new(),
            ex:        executor.executor_new(),
            result:    result_set.result_set_new(16),
            stats:     PipelineStats{
                parse_ok:    false,
                plan_type:   0,
                op_count:    0,
